import type { ModelTable, TargetDataModel } from '../planning/data-model.js';
import { entityDiagram, type EntityModel, type FieldKey } from './entity-diagram.js';

// RF-623, RF-508, DEC-134: the Mermaid entity-relationship diagram of the target data model,
// generated by code from the checked tables; the model never writes Mermaid. Each foreign key is a
// relation from the child table (zero or more rows) to the parent (exactly one, or at most one when
// a column of the key may be empty): the constraint states it, so nothing is guessed. Entity ids
// are generated from the table's position and never taken from names; `mask` hides secrets in
// names and types before the labels are coded by `entityDiagram`.

function keysOf(table: ModelTable, name: string): FieldKey[] {
  const keys: FieldKey[] = [];
  if (table.primaryKey.includes(name)) keys.push('PK');
  if (table.foreignKeys.some((key) => key.columns.includes(name))) keys.push('FK');
  if (table.uniqueKeys.some((key) => key.length === 1 && key[0] === name)) keys.push('UK');
  return keys;
}

function relationsOf(
  table: ModelTable,
  idOf: ReadonlyMap<string, string>,
  mask: (text: string) => string,
): EntityModel['relations'] {
  return table.foreignKeys.flatMap((key) => {
    const to = idOf.get(key.references);
    if (to === undefined) return [];
    const optional = table.columns.some((c) => key.columns.includes(c.name) && c.nullable);
    return [
      {
        ...{ from: idOf.get(table.name) ?? '', to, label: mask(key.columns.join(', ')) },
        fromCardinality: 'zero-or-more' as const,
        toCardinality: optional ? ('zero-or-one' as const) : ('one' as const),
      },
    ];
  });
}

// RF-623
export function targetModelDiagram(model: TargetDataModel, mask: (text: string) => string): string {
  const idOf = new Map(
    model.tables.map((table, index) => [table.name, `T${String(index + 1).padStart(3, '0')}`]),
  );
  const entities = model.tables.map((table) => ({
    cardId: idOf.get(table.name) ?? '',
    name: mask(table.name),
    fields: table.columns.map((column) => ({
      name: mask(column.name),
      type: mask(column.type),
      keys: keysOf(table, column.name),
    })),
  }));
  const relations = model.tables.flatMap((table) => relationsOf(table, idOf, mask));
  return entityDiagram({ entities, relations });
}
